scripts:
(()=>{'use strict';
const key='ielts-finished-book-v1';let state={version:1,fields:{},snapshots:{}},storageOK=true;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
try{const raw=localStorage.getItem(key);if(raw){const x=JSON.parse(raw);if(x.version===1&&x.fields&&x.snapshots)state=x}}catch(e){storageOK=false}
let toastTimeout;function notice(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').hidden=true,3500)}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('#save-status').textContent='文字已保存在当前浏览器'}catch(e){storageOK=false;$('#save-status').textContent='浏览器未允许保存，请导出作答';} }
function wordCounts(){$$('[data-wordcount]').forEach(el=>{const t=$(`[data-save="${el.dataset.wordcount}"]`);el.textContent=((t.value.trim().match(/\S+/g)||[]).length)+' 词（空白分隔计数）'})}
function scores(){$$('[data-score]').forEach(el=>{const id=el.dataset.score;$('#'+id+'-score').textContent=$$(`[data-score="${id}"]`).filter(x=>x.checked).length+' / '+el.dataset.total})}
function unlock(id){$$('#'+id+' .gated').forEach(el=>el.hidden=false);$$(`#${id} .first-stage [data-save]`).forEach(el=>{if(el.tagName==='SELECT')el.disabled=true;else el.readOnly=true});const b=$(`[data-freeze="${id}"]`);b.textContent='首次作答已保留';b.disabled=true;$(`[data-snapshot-status="${id}"]`).textContent='原稿已独立保存。请在下方练习区修订，重要答案及时导出。'}
function restore(){for(const el of $$('[data-save]')){const v=state.fields[el.dataset.save];if(v!==undefined){if(el.type==='checkbox')el.checked=!!v;else el.value=String(v)}}for(const id of Object.keys(state.snapshots)){if($('#'+id))unlock(id)}wordCounts();scores()}
restore();if(!storageOK)$('#save-status').textContent='浏览器未允许保存，请及时导出作答';
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.save){state.fields[el.dataset.save]=el.type==='checkbox'?el.checked:el.value;save();wordCounts();scores()}});
function show(id,anchor){if(!$('#'+id)?.classList.contains('panel'))id='guide';$$('main>.panel').forEach(el=>el.hidden=el.id!==id);$$('[data-go]').forEach(el=>{if(el.dataset.go===id)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});$$('audio').forEach(a=>a.pause());if(anchor){const target=$('#'+anchor);if(target){let p=target;while(p){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement}target.scrollIntoView({behavior:'smooth',block:'start'})}}else window.scrollTo(0,0)}
function route(){const h=decodeURIComponent(location.hash.slice(1))||'guide';let id=h;if(h.startsWith('topic-'))id='background';if(h.startsWith('usage-')||h==='core-words')id='vocabulary';for(const c of ['writing1','writing2','listening','speaking','reading'])if(h.startsWith(c+'-'))id=c;show(id,h!==id?h:null)}
window.addEventListener('hashchange',route);route();
window.prepareBackgroundPrint=()=>{document.body.classList.add('print-background');$$('details').forEach(d=>d.open=true);$$('main>.panel').forEach(p=>p.hidden=false);$$('img').forEach(p=>p.loading='eager')};
document.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go){if(location.hash==='#'+go.dataset.go)show(go.dataset.go);else location.hash=go.dataset.go}const freeze=e.target.closest('[data-freeze]');if(freeze){const id=freeze.dataset.freeze;const fields={};$$(`#${id} .first-stage [data-save]`).forEach(el=>fields[el.dataset.save]=el.value);const answerKeys=Object.keys(fields).filter(k=>/-q\d+$|-essay$|-record-note$/.test(k));if(!answerKeys.some(k=>String(fields[k]).trim())){notice('先留下答案或录音文件记录，再保存首次作答。');return}if(!state.snapshots[id])state.snapshots[id]={at:new Date().toISOString(),fields};save();unlock(id);$('#'+id+'-learn').scrollIntoView({behavior:'smooth'});notice('首次作答已保留，下面开始学习。')}});
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-export]');if(!btn)return;const kind=btn.dataset.export;let content;if(kind==='json')content=JSON.stringify(state,null,2);else{content='IELTS 四科学习册 · 我的作答\n导出时间：'+new Date().toLocaleString()+'\n\n';for(const [id,first] of Object.entries(state.snapshots)){content+='【'+id+' 首次原稿 · '+first.at+'】\n';for(const [k,v] of Object.entries(first.fields))content+=k+'：'+v+'\n';content+='\n'}content+='【练习、修订与复习记录】\n';for(const [k,v] of Object.entries(state.fields))content+=k+'：'+v+'\n';content+='\n录音需单独保存；本文件不包含音频。\n'}download(new Blob([content],{type:kind==='json'?'application/json':'text/plain;charset=utf-8'}),'IELTS-我的学习记录.'+(kind==='json'?'json':'txt'))});
$('#import-state').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const x=JSON.parse(await file.text());if(x.version!==1||!x.fields||typeof x.fields!=='object'||!x.snapshots||typeof x.snapshots!=='object')throw Error('格式不符');if(Object.keys(state.fields).length&&!confirm('恢复备份会替换当前文字记录。已导出当前记录后再继续？'))return;state=x;save();location.reload()}catch(err){notice('未能恢复：请选择本学习册导出的 JSON 备份。')}});
const timers={};document.addEventListener('click',e=>{const b=e.target.closest('[data-timer]');if(!b)return;const id=b.dataset.timer;if(timers[id]){clearInterval(timers[id].interval);delete timers[id];b.textContent='重新开始 '+b.dataset.minutes+' 分钟计时';return}const end=Date.now()+Number(b.dataset.minutes)*60000;b.textContent='停止计时';timers[id]={interval:setInterval(()=>{const left=Math.max(0,Math.ceil((end-Date.now())/1000));$('#timer-'+id).textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(!left){clearInterval(timers[id].interval);delete timers[id];b.textContent='本次计时结束';notice('时间到了，请保留此刻的答案。')}},250)}});
const recorders={},urls={};function showAudio(id,blob,name){if(urls[id])URL.revokeObjectURL(urls[id]);const u=URL.createObjectURL(blob);urls[id]=u;const player=$(`[data-preview="${id}"]`);player.src=u;player.hidden=false;const a=$(`[data-download="${id}"]`);a.href=u;a.download=name;a.hidden=false;a.textContent='下载录音';$(`[data-rec-status="${id}"]`).textContent='已载入 '+name+'；请下载保存，刷新页面不会保留声音。';const note=$(`[data-save="${id}-record-note"]`);if(note&&!note.readOnly){note.value=name;state.fields[note.dataset.save]=name;save()}}
document.addEventListener('click',async e=>{const start=e.target.closest('[data-record]'),stop=e.target.closest('[data-stop]');if(stop){recorders[stop.dataset.stop]?.rec.stop();return}if(!start)return;const id=start.dataset.record;if(!navigator.mediaDevices||!window.MediaRecorder){notice('当前浏览器不能录音，请用自己的录音器后载入文件。');return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const rec=new MediaRecorder(stream),chunks=[];recorders[id]={rec,stream};rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(chunks,{type:rec.mimeType});showAudio(id,blob,'IELTS-'+id+'-'+new Date().toISOString().replace(/[:.]/g,'-')+'.webm');start.disabled=false;$(`[data-stop="${id}"]`).disabled=true};rec.start();start.disabled=true;$(`[data-stop="${id}"]`).disabled=false;$(`[data-rec-status="${id}"]`).textContent='正在录音；完成后点击结束并保留。'}catch(err){notice('未能开启麦克风。可用自己的录音器，再载入音频。')}});
$$('[data-upload]').forEach(el=>el.addEventListener('change',e=>{const f=e.target.files[0];if(f)showAudio(el.dataset.upload,f,f.name)}));
$$('.review-stage details').forEach(d=>{if(/完成后|核对|参考/.test(d.querySelector('summary')?.textContent||''))d.classList.add('answer-note')});
const dialog=document.createElement('dialog');dialog.className='zoom-dialog';dialog.innerHTML='<button type="button">关闭原页大图</button><img alt="放大的原始题页">';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();$$('.original img').forEach(img=>{img.tabIndex=0;img.setAttribute('role','button');img.setAttribute('aria-label',img.alt+'；打开大图');const open=()=>{dialog.querySelector('img').src=img.src;dialog.showModal()};img.onclick=open;img.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}});
window.preparePrint=kind=>{$$('.work-area').forEach(area=>area.prepend(area.querySelector('.response')));document.body.classList.add(kind==='reference'?'print-reference':'print-student');$$('details').forEach(d=>d.open=true);$$('main>.panel').forEach(p=>p.hidden=false);$$('.gated').forEach(p=>p.hidden=false);$$('img').forEach(p=>p.loading='eager');const cover=document.createElement('section');cover.className='print-cover';cover.innerHTML='<p class="eyebrow">IELTS / ACADEMIC · 第一册</p><h1>'+(kind==='reference'?'参考册<br>完成后，再看。':'把理解变成<br>会用的英语。')+'</h1><p>'+(kind==='reference'?'答案、证据解释、可接受表达与新情境核对。<br>先保留自己的首答，再拿其中一处和参考比较。':'四科学习册 · 原题、作答页、教学练习与隔日检查。<br>阅读与写作分别完成；听力与口语使用随附原音。')+'</p><div class="cover-list">01　阅读：找到判断的证据<br>02　Task 1：把图表讲清楚<br>03　Task 2：让理由站得住<br>04　听力：听清最终要填什么<br>05　口语：说清一件物品的意义</div><p class="small">音频与可填写版本：解压后打开“开始学习.html”。<br>原题来自用户提供的 Cambridge 21 Academic 及 Cambridge 官方公开样题。<br>中文教学与部分迁移任务为工作区编写，考生样本保留原有错误。<br>本册用于首轮学习；完成一本或局部练习不直接换算 IELTS 分数。</p>';$('main').prepend(cover)};
})();

(()=>{'use strict';
const units=[...document.querySelectorAll('[data-enrichment]')];
function recordCount(){const el=document.querySelector('#enrichment-record-count');if(!el)return;const tasks=units.filter(u=>u.dataset.optional!=='true'),saved=tasks.filter(u=>field(u,'frozen').checked).length;el.textContent=saved+' / '+tasks.length+' 个补充练习首稿已保留。另有 '+units.filter(u=>u.dataset.optional==='true').length+' 个可选背景单元。'}
function field(el,name){return el.querySelector(`[data-save="enrich-${el.dataset.enrichment}-${name}"]`)}
function refresh(el){const frozen=field(el,'frozen').checked,optional=el.dataset.optional==='true';field(el,'answer').readOnly=frozen&&!optional;el.querySelector('.enrichment-feedback').hidden=!frozen;const button=el.querySelector('[data-enrich-freeze]');button.disabled=frozen;button.textContent=frozen?(optional?'理解提示已打开':'首稿已保留'):(optional?'已想过，查看理解提示':'保留首稿，打开反馈');if(frozen)el.querySelector('[data-enrich-status]').textContent=optional?'可以继续阅读；如愿意，也可以留下自己的理解与表达。':'首稿已保留于 '+field(el,'saved-at').value+'。请在下方修订；可在“学习记录”备份全部文字。'}
units.forEach(el=>{refresh(el);el.querySelector('[data-enrich-freeze]').addEventListener('click',()=>{if(!field(el,'answer').value.trim()&&el.dataset.optional!=='true'){el.querySelector('[data-enrich-status]').textContent='先留下答案或录音文件简记，再打开反馈。';field(el,'answer').focus();return}const time=field(el,'saved-at');time.value=new Date().toLocaleString();time.dispatchEvent(new Event('input',{bubbles:true}));const frozen=field(el,'frozen');frozen.checked=true;frozen.dispatchEvent(new Event('input',{bubbles:true}));refresh(el);recordCount();el.querySelector('.enrichment-feedback').scrollIntoView({block:'start',behavior:'smooth'})})});
recordCount();
})();

(()=>{'use strict';
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
 const chapters=['reading','listening','writing1','writing2','speaking'];
 const names={guide:'学习首页',background:'话题背景',vocabulary:'词汇与表达',reading:'阅读',listening:'听力',writing1:'写作 · Task 1',writing2:'写作 · Task 2',speaking:'口语',plan:'学习安排',records:'学习记录',library:'材料与规则',materials:'新增资料'};
 function stored(){try{const s=JSON.parse(localStorage.getItem('ielts-finished-book-v1')||'{}');return {fields:s.fields||{},snapshots:s.snapshots||{}}}catch{return {fields:{},snapshots:{}}}}
 function message(text){const box=$('#toast');box.textContent=text;box.hidden=false;clearTimeout(message.timeout);message.timeout=setTimeout(()=>box.hidden=true,4000)}
 function setMenu(open){document.body.classList.toggle('nav-open',open);$('#mobile-menu').setAttribute('aria-expanded',String(open));$('.nav-scrim').hidden=!open;if(open)$('.sidebar nav button[aria-current="page"]')?.focus();}
 $('#mobile-menu').addEventListener('click',()=>setMenu(!document.body.classList.contains('nav-open')));
 $('.nav-scrim').addEventListener('click',()=>setMenu(false));
 document.addEventListener('keydown',e=>{if(!document.body.classList.contains('nav-open'))return;if(e.key==='Escape'){setMenu(false);$('#mobile-menu').focus()}if(e.key==='Tab'){const nodes=$$('.sidebar a,.sidebar button').filter(el=>el.getClientRects().length),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
 document.addEventListener('click',e=>{if(e.target.closest('.sidebar [data-go],.sidebar a'))setMenu(false)});
 const articleNodes=$$('#background .topic-reader,#background .personal-reader');
 function backgroundView(hash){
   const catalog=$('.topic-catalog');const header=$('#background>.chapter-head');const isCatalog=hash==='background'||!hash.startsWith('topic-');
   catalog.classList.toggle('ui-filtered',!isCatalog);header.classList.toggle('ui-filtered',!isCatalog);
   articleNodes.forEach(n=>n.classList.add('ui-filtered'));
   $$('#background .topic-extension').forEach(n=>{n.classList.add('ui-filtered');n.classList.remove('ui-single')});
   if(!isCatalog){const target=document.getElementById(hash);if(target){target.classList.remove('ui-filtered');const extension=target.closest('.topic-extension');if(extension){extension.classList.remove('ui-filtered');if(target!==extension)extension.classList.add('ui-single');else extension.querySelectorAll('.personal-reader').forEach(a=>a.classList.remove('ui-filtered'));}requestAnimationFrame(()=>target.scrollIntoView({block:'start',behavior:'instant'}));}}
 }
 let vocabFilter='all';const cards=$$('.word-card,.usage-card');
 const extraVocab=$$('#vocabulary [data-enrichment]'),extraVocabSection=$('#vocabulary .enrichment-section');
 if(extraVocabSection){$('.vocab-toolbar').after(extraVocabSection);const b=document.createElement('button');b.dataset.vocabFilter='practice';b.setAttribute('aria-pressed','false');b.textContent='搭配练习 '+extraVocab.length;$('.filter-tabs').insertBefore(b,$('[data-vocab-filter="saved"]'));$('[data-vocab-filter="all"] span').textContent=String(cards.length+extraVocab.length);}
 function filterVocabulary(){const q=$('#vocab-search').value.trim().toLowerCase();let words=0,uses=0;
   for(const card of cards){const isWord=card.classList.contains('word-card'),saved=card.querySelector('.bookmark input').checked;const matchType=vocabFilter==='all'||(vocabFilter==='words'&&isWord)||(vocabFilter==='usage'&&!isWord)||(vocabFilter==='saved'&&saved);const visible=matchType&&(!q||card.textContent.toLowerCase().includes(q));card.classList.toggle('ui-filtered',!visible);if(visible){if(isWord)words++;else uses++;}}
   let extras=0;for(const card of extraVocab){const saved=card.querySelector('.bookmark input').checked,match=vocabFilter==='all'||vocabFilter==='practice'||(vocabFilter==='saved'&&saved),visible=match&&(!q||card.textContent.toLowerCase().includes(q));card.classList.toggle('ui-filtered',!visible);if(visible)extras++;}if(extraVocabSection)extraVocabSection.classList.toggle('ui-filtered',!extras);
   $('#core-words').classList.toggle('ui-filtered',!words);$('.word-grid').classList.toggle('ui-filtered',!words);$('#usage-cards').classList.toggle('ui-filtered',!uses);$('#usage-cards').nextElementSibling.classList.toggle('ui-filtered',!uses);$('.usage-grid').classList.toggle('ui-filtered',!uses);$('#vocab-empty').hidden=!!(words+uses+extras);$('#vocab-result').textContent=(words+uses+extras)+' 项内容'+(extras?' · 含 '+extras+' 组搭配练习':'')+(q?' · 已按关键词筛选':'');
   $$('[data-vocab-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.vocabFilter===vocabFilter)));
 }
 $$('[data-vocab-filter]').forEach(b=>b.addEventListener('click',()=>{vocabFilter=b.dataset.vocabFilter;filterVocabulary()}));$('#vocab-search').addEventListener('input',filterVocabulary);
 $$('.bookmark input').forEach(c=>c.addEventListener('change',filterVocabulary));
 $('#library-search').addEventListener('input',()=>{const q=$('#library-search').value.trim().toLowerCase();let n=0;$$('.source-file').forEach(a=>{const visible=a.textContent.toLowerCase().includes(q);a.classList.toggle('ui-filtered',!visible);if(visible)n++});$('#library-empty').hidden=!!n});
 function updateProgress(){const s=stored(),n=chapters.filter(c=>s.snapshots[c]).length;$('#home-count').textContent=n+' / 5';$('#home-progress').style.width=n*20+'%';$('#record-total').replaceChildren(document.createTextNode(String(n)+' '));const totalSmall=document.createElement('small');totalSmall.textContent='/ 5 章';$('#record-total').append(totalSmall);
   const setCount=(id,num,suffix)=>{const el=$(id);el.replaceChildren(document.createTextNode(String(num)+' '));const small=document.createElement('small');small.textContent=suffix;el.append(small)};
   const readCount=$$('[data-save^="topic-read-"]').filter(el=>el.checked).length;const savedCount=$$('.bookmark input,.tv-star input').filter(el=>el.checked).length;setCount('#record-topics',readCount,'/ 18 段');setCount('#record-saved',savedCount,'条内容');
   for(const cid of chapters){const done=!!s.snapshots[cid];const raw=s.fields[cid+'-minutes'];const meaningful=Object.entries(s.fields).some(([k,v])=>k.startsWith(cid+'-')&&/-q\d+$|-essay$|-record-note$/.test(k)&&String(v).trim());const label=done?'首次稿已保留':meaningful?'正在作答':'待开始';const state=$(`[data-chapter-state="${cid}"]`);state.textContent=label;state.classList.toggle('has-answer',done);$(`[data-record-status="${cid}"]`).textContent=label;$(`[data-record-minutes="${cid}"]`).textContent=raw!==undefined&&raw!==''?raw+' 分钟':'未记录用时';
     for(const a of $$(`#${cid} .chapter-outline [data-stage]`)){const locked=['learn','feedback'].includes(a.dataset.stage)&&!done;a.classList.toggle('is-locked',locked);a.setAttribute('aria-disabled',String(locked));}}
   $$('[data-read-status]').forEach(el=>{const input=$(`[data-save="topic-read-${el.dataset.readStatus}"]`);el.textContent=input?.checked?'已读过':'未标记'});
   const active=chapters.find(c=>!s.snapshots[c]&&Object.entries(s.fields).some(([k,v])=>k.startsWith(c+'-')&&/-q\d+$|-essay$|-record-note$/.test(k)&&String(v).trim()));
   const link=$('#next-link');if(active){$('#next-title').textContent='接着完成这份答案';$('#next-description').textContent=names[active]+'里已经有你的作答，继续时可以先回看。';link.firstChild.textContent='继续'+names[active]+' ';link.href='#'+active;}else if(n){$('#next-title').textContent='回看一次，修好一处';$('#next-description').textContent='已经保留了 '+n+' 份首次作答。回到自己的答案，挑一处具体问题修订。';link.firstChild.textContent='查看学习记录 ';link.href='#records';}else{document.getElementById('next-title').textContent='这一轮，从背景开始';document.getElementById('next-description').textContent='选一个熟悉的主题，看看意思如何组织成自然的英语。';link.firstChild.textContent='选一个话题 ';link.href='#background';}
 }
 function onRoute(){document.getElementById("toast").hidden=true;const hash=decodeURIComponent(location.hash.slice(1))||'guide';let pageId=hash;if(hash.startsWith('topic-'))pageId='background';if(hash.startsWith('usage-')||hash==='core-words')pageId='vocabulary';for(const c of chapters)if(hash.startsWith(c+'-'))pageId=c;$('#current-page-label').textContent=names[pageId]||'学习首页';document.title=(names[pageId]||'学习首页')+' · IELTS Work';backgroundView(hash);if(pageId==='vocabulary'&&(hash==='usage-cards'||hash==='core-words')){vocabFilter=hash==='usage-cards'?'usage':'words';$('#vocab-search').value='';filterVocabulary();requestAnimationFrame(()=>document.getElementById(hash)?.scrollIntoView({behavior:'instant',block:'start'}));}
   $$('.chapter-outline a').forEach(a=>a.classList.toggle('is-current',a.hash==='#'+hash||(hash===pageId&&a.hash==='#'+pageId+'-first')));updateProgress();}
 document.addEventListener('click',e=>{const a=e.target.closest('.chapter-outline a.is-locked');if(a){e.preventDefault();message('先保留本章的首次作答，再进入学习与反馈。');}if(e.target.closest('[data-freeze]'))requestAnimationFrame(updateProgress);});
 document.addEventListener('input',e=>{if(e.target.dataset.save)requestAnimationFrame(updateProgress)});
 window.addEventListener('hashchange',onRoute);filterVocabulary();onRoute();
})();

(()=>{'use strict';
const $=s=>document.querySelector(s),key='ielts-user-materials-v1',types={vocabulary:'词汇与搭配',topic:'话题背景',exercise:'题目与讲解',note:'其他资料'};let items=[],pending=[],editing=null,selected=null,storageError=false,vocabFilter='all';
const text=(tag,value,cls)=>{const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;return e};
